//! Actions-only real Common -> explicit user decision -> fresh target -> original
//! setStatus write, journal and retained SDK/consumer Join. No original SDK load.
use super::*;
use n::im_user_read_policy::NativeUserReadConfig;
fn config(root:&str,port:u16)->AccountConfig{let mut c=super::config(root,port,3000);c.profile.im_user_read=Some(NativeUserReadConfig{mark_read:true});assert!(c.profile.im_receipts.is_none()&&c.profile.im_sync.is_none());c}
fn status(latest:i64,yes:bool)->Vec<u8>{let mut w=Writer::new();w.boolean(yes).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();let l=latest.to_string();w.properties(&[RpcProperty{key:n::im_status::LATEST,value:l.as_bytes()}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn response(id:i32,yes:bool,code:u32)->Vec<u8>{let p=encode_reply(id,code,if yes{&[0,1,0,0,0,0]}else{&[0;6]}).unwrap();let mut r=vec![1];r.extend_from_slice(p.expose_to_transport());r}
fn rows(db:&crate::platform::db::Database)->Vec<(i64,Option<i32>,i64)>{db.with_conn(|c|{let mut q=c.prepare("SELECT state,request_id,target_index FROM app_voice_im_user_reads ORDER BY id").map_err(|_|"fixture")?;let values=q.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")?;values.collect::<Result<Vec<_>,_>>().map_err(|_|"fixture")}).unwrap()}
async fn poll(peer:&mut CommonPeer,p:&[u8]){let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(),"no user read replay or implicit request");let mut a=Reader::versioned(r.arguments).unwrap();a.bytes().unwrap();a.bytes().unwrap();let p=n::rpc_batch::read_payload(&mut a).unwrap();assert!(p.requests.is_empty());peer.send(&[reply(r.call_id,&n::runtime_backend::tests::swap_result(None,true,p.fields))]).await;}
async fn query(peer:&mut CommonPeer,method:&str)->Vec<u8>{loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let r=decode_request(&p[1..]).unwrap();if r.method==n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(){poll(peer,&p).await;continue;}assert_eq!(r.method,method.as_bytes());assert_eq!(r.metadata.len(),2);assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");return p;}}
async fn login_message(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();peer.send(&[reply(r.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");peer.send(&[message(91,7,true)]).await;next_reply(peer,91,true).await;}
async fn target(peer:&mut CommonPeer,latest:i64,yes:bool)->i32{let p=query(peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.u32().unwrap(),1);assert_eq!(a.bytes().unwrap(),b"1_2");peer.send(&[reply(r.call_id,&status(latest,yes))]).await;r.call_id}
async fn mark(peer:&mut CommonPeer)->i32{let p=query(peer,n::im_user_read_data::MARK_READ_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"1_2");assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"P:P_UDMR-N");assert_eq!(a.bytes().unwrap(),b"7");assert!(a.i64().unwrap()>0);a.finish().unwrap();r.call_id}
async fn scenario(yes:bool,code:u32){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(finish,wait)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;assert!(rows(&db).is_empty(),"installation/received body is not user consent");ready.send(()).unwrap();target(&mut peer,9,true).await;let id=mark(&mut peer).await;assert_eq!(rows(&db),[(0,Some(id),7)]);peer.send(&[response(id,yes,code)]).await;wait.await.unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap().pop().unwrap();assert!(manager.get(&line,100).await.unwrap().im_user_read_supported.unwrap());
    let first=bounded(manager.mark_im_user_read(&line,account.revision,message.id,&"a".repeat(32),true)).await.unwrap();assert_eq!(first.state,if yes&&code==0{"confirmed"}else{"rejected"});let again=bounded(manager.mark_im_user_read(&line,account.revision,message.id,&"a".repeat(32),true)).await.unwrap();assert_eq!(again.id,first.id);assert_eq!(rows(&temp.database).len(),1);assert!(manager.messages(&line,16).unwrap().is_empty());assert!(temp.database.get_call_history_for_line(&line,16,0).unwrap().is_empty());finish.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}
#[tokio::test]async fn user_read_account_explicit_action_has_original_target_and_write_result_and_same_nonce_no_replay(){Box::pin(scenario(true,0)).await;}
#[tokio::test]async fn user_read_account_original_false_and_version_rejections_keep_sdk_healthy_without_retry(){Box::pin(async{scenario(false,0).await;scenario(false,65537).await;}).await;}
#[tokio::test]
async fn user_read_account_no_consent_and_old_revision_do_not_query_or_write(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(finish,wait)=tokio::sync::oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;ready.send(()).unwrap();wait.await.unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap().pop().unwrap();assert_eq!(manager.mark_im_user_read(&line,account.revision,message.id,&"a".repeat(32),false).await.err(),Some("app_account_im_user_read_consent_required"));assert_eq!(manager.mark_im_user_read(&line,2,message.id,&"a".repeat(32),true).await.err(),Some("app_account_revision_conflict"));assert!(rows(&temp.database).is_empty());finish.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn user_read_account_missing_current_target_never_records_unknown_write_or_changes_sdk_state(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(finish,wait)=tokio::sync::oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;ready.send(()).unwrap();target(&mut peer,6,true).await;wait.await.unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap().pop().unwrap();assert_eq!(bounded(manager.mark_im_user_read(&line,account.revision,message.id,&"a".repeat(32),true)).await.err(),Some("app_account_im_user_read_target_unconfirmed"));assert!(rows(&temp.database).is_empty());assert_eq!(manager.get(&line,100).await.unwrap().phase,"hosted");finish.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn user_read_account_cancel_at_submitted_target_query_ignores_late_reply_without_user_write_or_sdk_disconnect(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(queried,observed)=tokio::sync::oneshot::channel();let(go,wait)=tokio::sync::oneshot::channel();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_message(&mut peer).await;ready.send(()).unwrap();let p=query(&mut peer,n::im_status::REFRESH_METHOD).await;let id=decode_request(&p[1..]).unwrap().call_id;queried.send(()).unwrap();wait.await.unwrap();peer.send(&[reply(id,&[0]),message(95,7,true)]).await;next_reply(&mut peer,95,true).await;done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let message=manager.im_messages(&line,16).unwrap().pop().unwrap();let nonce="a".repeat(32);let mut reading=Box::pin(manager.mark_im_user_read(&line,account.revision,message.id,&nonce,true));tokio::select!{r=reading.as_mut()=>panic!("target query is pending: {r:?}"),r=observed=>r.unwrap()};let submitted=async{while !manager.user_read_target_was_submitted(&line){tokio::task::yield_now().await;}};tokio::select!{r=reading.as_mut()=>panic!("original target has no reply: {r:?}"),_=bounded(submitted)=>{}};drop(reading);go.send(()).unwrap();bounded(finished).await.unwrap();assert!(rows(&temp.database).is_empty());assert_eq!(manager.get(&line,100).await.unwrap().phase,"hosted");assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn user_read_account_unknown_write_timeout_true_stop_restart_blocks_new_nonce_without_any_target_or_write_replay(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(second,started_again)=tokio::sync::oneshot::channel();let(finish,wait)=tokio::sync::oneshot::channel();let db=temp.database.clone();
    let serving=tokio::spawn(async move{bounded(async move{let original=listener.into_std().unwrap();let next=TcpListener::from_std(original.try_clone().unwrap()).unwrap();let first=TcpListener::from_std(original).unwrap();let mut peer=CommonPeer::open(first,server.clone()).await;login_message(&mut peer).await;ready.send(()).unwrap();target(&mut peer,9,true).await;let id=mark(&mut peer).await;assert_eq!(rows(&db),[(0,Some(id),7)]);while let Some(p)=peer.next().await{poll(&mut peer,&p).await;}let mut peer=CommonPeer::open(next,server).await;login_message(&mut peer).await;second.send(()).unwrap();wait.await.unwrap();assert_eq!(rows(&db),[(0,Some(id),7)]);finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let id=manager.im_messages(&line,16).unwrap()[0].id;assert!(bounded(manager.mark_im_user_read(&line,account.revision,id,&"a".repeat(32),true)).await.is_err());bounded(async{while manager.get(&line,100).await.unwrap().phase!="disconnected"{tokio::time::sleep(Duration::from_millis(5)).await;}}).await;assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(started_again).await.unwrap();assert_eq!(bounded(manager.mark_im_user_read(&line,account.revision,id,&"b".repeat(32),true)).await.err(),Some("app_account_im_user_read_uncertain"));assert_eq!(manager.im_user_read_history(&line,16).unwrap()[0].state,"uncertain");assert_eq!(manager.im_messages(&line,16).unwrap().len(),1);finish.send(()).unwrap();assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
